// PSEC generated-contract drift gate.
//
// The `mxc_alpha_process_security_environment_spec` crate under src/core/generated/ is
// generated by `flatc` from the vendored schema
// external/windows-sdk/ProcessSecurityEnvironment.fbs. This gate:
//
//   1. verifies the vendored schema SHA-256 matches the recorded provenance
//      (external/windows-sdk/ProcessSecurityEnvironment.provenance.toml);
//   2. verifies every committed generated file carries the flatc "do not
//      modify." header (a hand-edit guard);
//   3. performs a REAL regenerate-and-diff with the EXACT pinned flatc: it
//      downloads the pinned platform release asset from the flatbuffers GitHub
//      release, verifies its SHA-256 against the provenance, unzips it,
//      regenerates into a temp directory with the same flags, reorganizes +
//      patches lib.rs, runs `cargo fmt`, and recursively diffs the result
//      against the committed src/; and
//   4. `cargo check`s the committed workspace crate for cross-target compile
//      validation.
//
// To reuse a cached flatc (e.g. on a Windows dev box, or an air-gapped runner)
// and skip the download, pass `--flatc <path>` or set the `FLATC` env var. The
// binary's version must equal the pinned flatc_version.
//
// Run from anywhere (paths resolved relative to repo root):
//   node scripts/versioning/check-psec-codegen.js [--flatc <path-to-flatc>]

const fs = require("fs");
const os = require("os");
const crypto = require("crypto");
const { join, relative, sep } = require("path");
const { execFileSync } = require("child_process");

const repoRoot = join(__dirname, "..", "..");
const schemaPath = join(repoRoot, "external", "windows-sdk", "ProcessSecurityEnvironment.fbs");
const provenancePath = join(
  repoRoot,
  "external",
  "windows-sdk",
  "ProcessSecurityEnvironment.provenance.toml"
);
const crateDir = join(
  repoRoot,
  "src",
  "core",
  "generated",
  "process_security_environment_specification"
);
const committedSrcDir = join(crateDir, "src");

function fail(msg) {
  console.error("PSEC codegen check FAILED:");
  console.error("  - " + msg);
  process.exit(1);
}

const sha256Hex = (buf) => crypto.createHash("sha256").update(buf).digest("hex");
const sha256File = (p) => sha256Hex(fs.readFileSync(p));
// LF-normalize so autocrlf checkouts don't produce false differences.
const lfNormalize = (buf) =>
  Buffer.from(buf.toString("binary").replace(/\r\n/g, "\n"), "binary");

// --- Minimal TOML reader (targeted, no dependency) --------------------------
function tomlSection(text, header) {
  const lines = text.split(/\r?\n/);
  const marker = `[${header}]`;
  const start = lines.findIndex((line) => line.trim() === marker);
  if (start === -1) return null;
  let end = start + 1;
  while (end < lines.length && !lines[end].trimStart().startsWith("[")) {
    end++;
  }
  return lines.slice(start + 1, end).join("\n");
}
function tomlString(block, key) {
  if (block == null) return null;
  for (const line of block.split(/\r?\n/)) {
    const separator = line.indexOf("=");
    if (separator === -1 || line.slice(0, separator).trim() !== key) continue;
    const value = line.slice(separator + 1).trim();
    const match = /^"([^"]+)"(?:\s+#.*)?$/.exec(value);
    return match ? match[1] : null;
  }
  return null;
}

function readProvenance() {
  let text;
  try {
    text = fs.readFileSync(provenancePath, "utf8");
  } catch (e) {
    fail(`could not read provenance ${provenancePath}: ${e.message}`);
  }
  const schemaSha = tomlString(tomlSection(text, "schema"), "sha256");
  if (!schemaSha) fail(`provenance missing [schema].sha256: ${provenancePath}`);
  const flatcVersion = tomlString(tomlSection(text, "tool"), "flatc_version");
  if (!flatcVersion) fail(`provenance missing [tool].flatc_version: ${provenancePath}`);
  const asset = (osName) => {
    const b = tomlSection(text, `tool.flatc_assets.${osName}`);
    const name = tomlString(b, "name");
    const sha256 = tomlString(b, "sha256");
    return name && sha256 ? { name, sha256: sha256.toLowerCase() } : null;
  };
  return {
    schemaSha: schemaSha.toLowerCase(),
    flatcVersion,
    assets: { linux: asset("linux"), windows: asset("windows") },
  };
}

// --- flatc acquisition ------------------------------------------------------
function flatcReportedVersion(flatc) {
  const out = execFileSync(flatc, ["--version"], { encoding: "utf8" });
  const m = out.match(/flatc version (\d+\.\d+\.\d+)/);
  if (!m) fail(`could not parse flatc version from: ${out.trim()}`);
  return m[1];
}

function cliFlatc() {
  const i = process.argv.indexOf("--flatc");
  if (i !== -1 && process.argv[i + 1]) return process.argv[i + 1];
  if (process.env.FLATC) return process.env.FLATC;
  return null;
}

function acquireFlatc(prov, tmp) {
  const provided = cliFlatc();
  if (provided) {
    const v = flatcReportedVersion(provided);
    if (v !== prov.flatcVersion) {
      fail(
        `provided flatc version ${v} != pinned ${prov.flatcVersion} ` +
          `(--flatc / FLATC=${provided})`
      );
    }
    return provided;
  }

  const platform = process.platform;
  const asset =
    platform === "win32"
      ? prov.assets.windows
      : platform === "linux"
      ? prov.assets.linux
      : null;
  if (!asset) {
    fail(
      `no pinned flatc release asset for platform '${platform}'. ` +
        `Set FLATC=<path to flatc ${prov.flatcVersion}> to run the drift check here.`
    );
  }

  const url = `https://github.com/google/flatbuffers/releases/download/v${prov.flatcVersion}/${asset.name}`;
  const zip = join(tmp, asset.name);
  console.log(`Downloading pinned flatc asset ${asset.name} ...`);
  execFileSync("curl", ["-fsSL", "-o", zip, url], {
    stdio: ["ignore", "ignore", "inherit"],
  });
  const got = sha256File(zip);
  if (got !== asset.sha256) {
    fail(
      `flatc asset SHA-256 mismatch for ${asset.name}:\n` +
        `    expected: ${asset.sha256}\n` +
        `    actual:   ${got}`
    );
  }

  const outDir = join(tmp, "flatc");
  fs.mkdirSync(outDir, { recursive: true });
  if (platform === "win32") {
    execFileSync(
      "powershell",
      [
        "-NoProfile",
        "-NonInteractive",
        "-Command",
        `Expand-Archive -Path '${zip}' -DestinationPath '${outDir}' -Force`,
      ],
      { stdio: ["ignore", "ignore", "inherit"] }
    );
  } else {
    execFileSync("unzip", ["-o", "-q", zip, "-d", outDir], {
      stdio: ["ignore", "ignore", "inherit"],
    });
  }

  const bin = join(outDir, platform === "win32" ? "flatc.exe" : "flatc");
  if (!fs.existsSync(bin)) fail(`flatc binary not found after extracting ${asset.name}`);
  if (platform !== "win32") fs.chmodSync(bin, 0o755);

  const v = flatcReportedVersion(bin);
  if (v !== prov.flatcVersion) {
    fail(`downloaded flatc version ${v} != pinned ${prov.flatcVersion}`);
  }
  return bin;
}

// --- Regeneration (mirrors regenerate.ps1, into a temp dir) -----------------
const FMT_MANIFEST = `[package]
name = "mxc_alpha_process_security_environment_spec"
version = "0.7.0"
edition = "2021"
license = "MIT"
publish = false

[dependencies]
flatbuffers = "25"
`;

function regenerate(flatc, tmp) {
  const genCrate = join(tmp, "gen");
  fs.mkdirSync(genCrate, { recursive: true });
  execFileSync(
    flatc,
    [
      "--rust",
      "--gen-object-api",
      "--force-empty",
      "--no-prefix",
      "--rust-module-root-file",
      "--gen-all",
      "-o",
      genCrate,
      schemaPath,
    ],
    { stdio: ["ignore", "ignore", "inherit"] }
  );

  const genSrc = join(genCrate, "src");
  fs.mkdirSync(genSrc);
  fs.renameSync(join(genCrate, "mod.rs"), join(genSrc, "lib.rs"));
  fs.renameSync(
    join(genCrate, "process_security_environment_layout"),
    join(genSrc, "process_security_environment_layout")
  );

  const libRs = join(genSrc, "lib.rs");
  const patched = fs
    .readFileSync(libRs, "utf8")
    .replace(
      "// @generated",
      "// @generated\n#![allow(unused_imports, non_snake_case, non_camel_case_types, clippy::all)]"
    );
  fs.writeFileSync(libRs, patched);

  fs.writeFileSync(join(genCrate, "Cargo.toml"), FMT_MANIFEST);
  execFileSync("cargo", ["fmt", "--manifest-path", join(genCrate, "Cargo.toml")], {
    stdio: ["ignore", "ignore", "inherit"],
  });
  return genSrc;
}

function collectRel(dir) {
  const out = [];
  (function walk(d) {
    for (const e of fs.readdirSync(d).sort()) {
      const p = join(d, e);
      if (fs.statSync(p).isDirectory()) walk(p);
      else out.push(relative(dir, p).split(sep).join("/"));
    }
  })(dir);
  return out.sort();
}

function diffTrees(committed, generated) {
  const a = collectRel(committed);
  const b = collectRel(generated);
  const setA = new Set(a);
  const setB = new Set(b);
  const onlyCommitted = a.filter((x) => !setB.has(x));
  const onlyGen = b.filter((x) => !setA.has(x));
  if (onlyCommitted.length || onlyGen.length) {
    fail(
      "generated file set drifted from committed:\n" +
        (onlyCommitted.length
          ? "    committed-only: " + onlyCommitted.join(", ") + "\n"
          : "") +
        (onlyGen.length ? "    generated-only: " + onlyGen.join(", ") : "")
    );
  }
  for (const rel of a) {
    const c = lfNormalize(fs.readFileSync(join(committed, rel))).toString().split("\n");
    const g = lfNormalize(fs.readFileSync(join(generated, rel))).toString().split("\n");
    if (c.join("\n") !== g.join("\n")) {
      let line = 0;
      while (line < c.length && line < g.length && c[line] === g[line]) line++;
      const show = (arr) => (line < arr.length ? JSON.stringify(arr[line]) : "<end of file>");
      fail(
        `committed generated output is stale at src/${rel}.\n` +
          `    First difference at line ${line + 1}:\n` +
          `      committed:   ${show(c)}\n` +
          `      regenerated: ${show(g)}\n` +
          `    Regenerate with the crate's regenerate.ps1 (exact flatc ` +
          `${provInfo.flatcVersion}).`
      );
    }
  }
  return a.length;
}

// ============================================================================
const provInfo = readProvenance();

// --- 1. Schema hash matches provenance --------------------------------------
let schemaBytes;
try {
  schemaBytes = fs.readFileSync(schemaPath);
} catch (e) {
  fail(`could not read schema ${schemaPath}: ${e.message}`);
}
const actualSchemaSha = sha256Hex(lfNormalize(schemaBytes));
if (actualSchemaSha !== provInfo.schemaSha) {
  fail(
    `vendored schema hash drifted from provenance.\n` +
      `    schema:   ${schemaPath}\n` +
      `    expected: ${provInfo.schemaSha}  (${provenancePath})\n` +
      `    actual:   ${actualSchemaSha}\n` +
      `    If you intentionally refreshed the schema, update the provenance\n` +
      `    (sha256 + source build) and regenerate the bindings (see the crate README).`
  );
}

// --- 2. Generated files carry the "do not modify" header --------------------
function isMarkedGenerated(text) {
  const head = text.slice(0, 400).toLowerCase();
  return head.includes("@generated") && head.includes("do not modify");
}
if (!fs.existsSync(committedSrcDir)) {
  fail(`generated source directory not found: ${committedSrcDir}`);
}
const committedFiles = collectRel(committedSrcDir);
if (committedFiles.length === 0) {
  fail(`no generated files found under ${committedSrcDir}`);
}
const unmarked = committedFiles.filter(
  (rel) => !isMarkedGenerated(fs.readFileSync(join(committedSrcDir, rel), "utf8"))
);
if (unmarked.length > 0) {
  fail(
    "generated file(s) are missing the flatc 'do not modify' header (hand-edited?):\n" +
      unmarked.map((f) => "      src/" + f).join("\n")
  );
}

// --- 3. Real regenerate-and-diff with the exact pinned flatc ----------------
const tmpBase = fs.mkdtempSync(join(os.tmpdir(), "mxc-psec-"));
let comparedCount;
try {
  const flatc = acquireFlatc(provInfo, tmpBase);
  const genSrc = regenerate(flatc, tmpBase);
  comparedCount = diffTrees(committedSrcDir, genSrc);
} finally {
  fs.rmSync(tmpBase, { recursive: true, force: true });
}

// --- 4. Committed workspace crate compiles (cross-target validation) --------
try {
  execFileSync("cargo", ["check", "-q", "-p", "mxc_alpha_process_security_environment_spec"], {
    cwd: join(repoRoot, "src"),
    stdio: ["ignore", "ignore", "inherit"],
  });
} catch (e) {
  fail(
    `committed crate failed to compile via ` +
      `'cargo check -p mxc_alpha_process_security_environment_spec': ${e.message}`
  );
}

console.log(
  `PSEC codegen OK: schema matches provenance (sha256 ${provInfo.schemaSha.slice(0, 12)}…), ` +
    `regenerated with pinned flatc ${provInfo.flatcVersion} and diffed ${comparedCount} files ` +
    `(no drift), all carry the do-not-modify header, and the crate compiles.`
);
